/**
 * XML sitemap for Ellixorrr.
 *
 * Generated by Next.js App Router at /sitemap.xml.
 *
 * Includes only genuinely indexable public pages — the three locale
 * homepages. Auth, dashboard, and admin routes are intentionally excluded
 * because they are protected by server-side authorization and contain no
 * public content.
 *
 * Uses absolute URLs built from NEXT_PUBLIC_SITE_URL (fallback:
 * https://ellixorrr.dpdns.org).
 */
import { MetadataRoute } from "next";
import { locales } from "@/i18n/config";
import { absoluteUrl } from "@/lib/site-config";

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const entries: MetadataRoute.Sitemap = locales.map((locale) => ({
    url: absoluteUrl(locale, "/"),
  }));

  return entries;
}
